        local connection = signal:Connect(handler)
        table.insert(connections, connection)
        return connection
    end
    local root
    for _, record in ipairs(DATA) do
        local id, class, _, props = record[1], record[2], record[3], record[4]
        local ok, obj = pcall(Instance.new, class)
        if ok then
            refs[id] = obj
            for name, value in pairs(props) do
                if value ~= nil then pcall(function() obj[name] = value end) end
            end
        end
    end
    for _, record in ipairs(DATA) do
        local id, _, parentId = record[1], record[2], record[3]
        if refs[id] and refs[parentId] then refs[id].Parent = refs[parentId] end
    end
    root = refs[0]
    assert(root and root:IsA('ScreenGui'), 'Captured ScreenGui is unavailable')
    root.Name = 'DeltaCapturedCustom'
    root.Enabled = false
    root.ResetOnSpawn = false
    root.DisplayOrder = 10000
    local host = nil
    if type(gethui) == 'function' then
        local ok, ui = pcall(gethui)
        if ok and typeof(ui) == 'Instance' then host = ui end
    end
    if not host then host = player and player:FindFirstChildOfClass('PlayerGui') end
    if not host then host = game:GetService('CoreGui') end
    local okParent = pcall(function() root.Parent = host end)
    if not okParent then
        host = player and player:WaitForChild('PlayerGui') or game:GetService('CoreGui')
        root.Parent = host
    end
    local function obj(id) return refs[id] end
    local function show(id, value) local inst=obj(id); if inst then inst.Visible=value end end
    local function text(id, value) local inst=obj(id);if inst and (inst:IsA('TextLabel') or inst:IsA('TextBox')) then inst.Text=tostring(value) end end
    local function new(class, props, parent)
        local inst=Instance.new(class)
        for k, v in pairs(props) do pcall(function() inst[k]=v end) end
        inst.Parent=parent
        return inst
    end
    local function corner(inst, radius)
        new('UICorner', {CornerRadius=UDim.new(0,radius or 8)},inst)
    end
    local theme = Color3.fromRGB(65,151,238)
    local dark = Color3.fromRGB(28,30,42)
    local white = Color3.fromRGB(236,242,255)
    local message = [[
Thank you for using this gloriously unnecessary custom Delta-style GUI. This build was made for me with help from ChatGPT, because apparently giving an AI hundreds of UI objects and asking it to wire every last button is considered a normal Friday night activity.

Our totally overdramatic, extremely serious website announcement: the official website for ChatGPT is https://chatgpt.com. Yes, the very same place where someone asked a chatbot to turn a Roblox interface dump into two executors just because having both a key system and a keyless edition sounded funny.

This is an independent fan-made interface, NOT the official Delta executor, NOT an official OpenAI app, and NOT affiliated with either service. No secret activation fees, no mystery key ads, no fake anti-ban promises. Use scripts responsibly; the executor you're already running supplies the actual Lua execution capability.

Thank you again for choosing the version of human ingenuity where the buttons have jobs, the console actually reports errors, and the credits section refuses to stop talking. Custom build powered by questionable ambition and an alarmingly patient language model.]]
    local state = {tabs={{id=1,name='script1.lua',code='-- Custom Delta-style GUI | ChatGPT assisted\nprint("Hello from your custom executor!")'}}, nextTab=2, active=1,
        scripts={}, settings={autoExec=false, antiAFK=false, console=true, autoClose=false, fps='60 FPS',iconSize='Medium',iconShape='Squircle',iconColor='Blue'}, entries={}, opened=true, page='Executor'}
    local persistPath = 'delta_custom_workspace.json'
    if type(readfile)=='function' then
        local success, data=pcall(readfile,persistPath)
        if success and type(data)=='string' then
            local good, stored=pcall(HttpService.JSONDecode,HttpService,data)
            if good and type(stored)=='table' then
                if type(stored.tabs)=='table' and #stored.tabs>0 then
                    local tabs={}
                    for _,t in ipairs(stored.tabs) do
                        if #tabs>=16 then break end
                        if type(t)=='table' and type(t.code)=='string' and #t.code<1048577 then
                            table.insert(tabs,{id=#tabs+1,name=tostring(t.name or 'script.lua'):sub(1,80),code=t.code})
                        end
                    end
                    if #tabs>0 then state.tabs=tabs;state.nextTab=#tabs+1 end
                end
                if type(stored.scripts)=='table' then
                    for _,s in ipairs(stored.scripts) do
                        if #state.scripts>=64 then break end
                        if type(s)=='table' and type(s.code)=='string' and #s.code<=1048576 then
                            table.insert(state.scripts,{name=tostring(s.name or 'Script'):sub(1,80),code=s.code})
                        end
                    end
                end
                if type(stored.settings)=='table' then
                    for key,value in pairs(state.settings) do
                        if type(stored.settings[key])==type(value) then state.settings[key]=stored.settings[key] end
                    end
                end
            end
        end
    end
    local function saveState()
        if type(writefile)~='function' then return false,'Executor file writing is unavailable' end
