    end
    local COLORS={output=Color3.fromRGB(195,217,246),info=Color3.fromRGB(107,178,248),warning=Color3.fromRGB(255,205,105),error=Color3.fromRGB(255,119,119)}
    local function redrawLogs()
        for _,id in ipairs({656,689}) do
            local holder=obj(id)
            if holder then
                for _,child in ipairs(holder:GetChildren()) do
                    if child.Name=='CapturedLog' then child:Destroy() end
                end
                local query = (obj(id==656 and 662 or 695) and obj(id==656 and 662 or 695).Text or ''):lower()
                local count=0
                for _,entry in ipairs(state.entries) do
                    if (id==689 or entry.channel=='roblox') and (query=='' or entry.text:lower():find(query,1,true)) then
                        local label=new('TextLabel',{Name='CapturedLog',BackgroundTransparency=1,Text=entry.text,
                            Font=Enum.Font.Code,TextColor3=COLORS[entry.kind] or COLORS.output,TextSize=13,
                            TextXAlignment=Enum.TextXAlignment.Left,TextYAlignment=Enum.TextYAlignment.Top,
                            TextWrapped=true,Size=UDim2.new(1,-18,0,36),Position=UDim2.fromOffset(8,8+count*38),ZIndex=50},holder)
                        count=count+1
