    local function httpGet(url)
        -- The calling executor determines which networking APIs are available.
        local methods={
            function() return game:HttpGet(url) end,
            function() return HttpService:GetAsync(url) end,
        }
        local executorRequest=(type(request)=='function' and request)
            or (type(http_request)=='function' and http_request)
            or (type(syn)=='table' and type(syn.request)=='function' and syn.request)
        if executorRequest then table.insert(methods,1,function()
            local reply=executorRequest({Url=url,Method='GET'})
            if type(reply)~='table' or (reply.StatusCode and reply.StatusCode>=400) then
                error('HTTP '..tostring(reply and reply.StatusCode))
            end
            return reply.Body
        end) end
        local last='HTTP access unavailable'
        for _,method in ipairs(methods) do
            local ok, result=pcall(method)
            if ok and type(result)=='string' and #result>0 then return result end
            last=tostring(result)
        end
        error(last)
    end
    local function scriptCode(item)
        if type(item.script)=='string' and item.script~='' then return item.script end
        if type(item._id)~='string' or not item._id:match('^[%w_%-]+$') then
            error('ScriptBlox did not return a valid script ID')
        end
        local parsed=HttpService:JSONDecode(httpGet('https://scriptblox.com/api/script/'..item._id))
        local entry=type(parsed)=='table' and parsed.script or nil
        if type(entry)=='table' and type(entry.script)=='string' then return entry.script end
        error('ScriptBlox returned no script source')
    end
