        remote.sequence+=1
        local sequence=remote.sequence
        local search=remote.query
        local page=remote.page
        hubStatus.Text='Powered by ScriptBlox.com | Loading scripts...'
        task.spawn(function()
            local url='https://scriptblox.com/api/script/'..(search=='' and 'fetch' or 'search')
                ..'?page='..tostring(page)..'&max=20&mode=free&patched=0'
            if search~='' then url..='&q='..urlEncode(search) end
            local ok,data=pcall(function()
                local decoded=HttpService:JSONDecode(httpGet(url))
                assert(type(decoded)=='table' and type(decoded.result)=='table'
                    and type(decoded.result.scripts)=='table',
                    'Unexpected ScriptBlox API response')
                return decoded.result
            end)
            if sequence~=remote.sequence or isClosed then return end
            if not ok then
                hubStatus.Text='ScriptBlox request failed. Check console / network.'
                log('error','ScriptBlox: '..tostring(data));return
            end
            remote.list={}
            for _,item in ipairs(data.scripts) do
                if type(item)=='table' and type(item.title)=='string' then
                    table.insert(remote.list,item)
                end
            end
            remote.totalPages=math.max(1,math.min(1000,tonumber(data.totalPages) or page))
            showHubResults()
        end)
    end
