            else if feedback then feedback.Text='Wrong key. Hint: click GET THE KEY.' end end
        end
        if obj(14) then link(obj(14).Activated,validate) end
        if keyInput then link(keyInput.FocusLost,function(enter)if enter then validate()end end)end
        if obj(18) then link(obj(18).Activated,function()
            if type(setclipboard)=='function' then pcall(setclipboard,'CHATGPT-MADE-THIS') end
            if feedback then feedback.Text='KEY: CHATGPT-MADE-THIS' end
        end)end
        if obj(29) then link(obj(29).Activated,function()
            if feedback then feedback.Text='Enter the key to unlock this edition.' end
        end)end
        if not KEYED then keyPanel:Destroy() end
    end
    local frameCounter,lastTime=0,os.clock()
    link(RunService.RenderStepped,function()
        frameCounter+=1
        if os.clock()-lastTime>=1 then
            text(540,string.format('<font color="#4FA4F2">%d</font> FPS',frameCounter))
            text(542,string.format('<font color="#4FA4F2">%d</font> players',#Players:GetPlayers()))
            local ping='?'
            local ok, result=pcall(function()return math.floor(player:GetNetworkPing()*1000)end)
            if ok then ping=tostring(result) end
            text(541,'<font color="#4FA4F2">'..ping..'</font> MS Ping')
            frameCounter=0;lastTime=os.clock()
        end
    end)
    link(UserInputService.InputBegan,function(input,handled)
        if handled and not (UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) or UserInputService:IsKeyDown(Enum.KeyCode.RightControl)) then return end
        local ctrl=UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) or UserInputService:IsKeyDown(Enum.KeyCode.RightControl)
        if input.KeyCode==Enum.KeyCode.RightControl then setOpen(not state.opened) end
        if not unlocked then return end
        if ctrl and input.KeyCode==Enum.KeyCode.S then
            local name=activeTab().name
            local found=false
            for _,s in ipairs(state.scripts) do if s.name==name then s.code=activeTab().code;found=true end end
            if not found and #state.scripts<64 then table.insert(state.scripts,{name=name,code=activeTab().code}) end
            local ok=saveState();renderLibrary();toast(ok and ('Saved '..name) or 'Saved to in-session library only')
        elseif ctrl and input.KeyCode==Enum.KeyCode.V and not (UserInputService:GetFocusedTextBox()) then
            clipboardAction(false)
        end
    end)
    link(LogService.MessageOut,function(value,kind)
        if not state.settings.console then return end
        local label='output'
        if kind==Enum.MessageType.MessageError then label='error'
        elseif kind==Enum.MessageType.MessageWarning then label='warning' end
        log(label,value,'roblox')
    end)
    local function cleanup()
        isClosed=true
        remote.sequence+=1
        saveState()
        for _,c in ipairs(connections) do pcall(function()c:Disconnect()end) end
        if root and root.Parent then root:Destroy() end
    end
    env.__DeltaCapturedUI={close=cleanup,gui=root,state=state}
    renderTabs()
    openPage('Executor')
    if KEYED then
        state.opened=false
        for _,id in pairs(NAV) do show(id,false) end
        show(32,false)
    else setOpen(true) end
    root.Enabled=true
    log('info',KEYED and 'Keyed edition ready. Click GET THE KEY for the joke key.' or 'Keyless edition ready. Editor opened immediately.')
    if state.settings.autoExec and type(listfiles)=='function' and type(readfile)=='function' then
        local ok,files=pcall(listfiles,'delta_autoexec')
        if ok and type(files)=='table' then
            for _,path in ipairs(files) do
                if type(path)=='string' and (path:match('%.lua$') or path:match('%.luau$')) then
                    local got,code=pcall(readfile,path)
                    if got then run(code,path) end
                end
            end
        end
    end
    return env.__DeltaCapturedUI
end

end)()
return function(keyed) return mount(DATA,keyed == true) end
